-- =============================================================================
-- ecommerce_db — PostgreSQL port of the MySQL schema (schema.sql)
-- Target: PostgreSQL 13+ (tested on 16)
--
-- Run with psql while connected to a maintenance DB (e.g. postgres):
--     psql -U postgres -d postgres -f schema_postgresql.sql
--
-- MySQL -> PostgreSQL mapping used:
--   BIGINT AUTO_INCREMENT     -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--   DATETIME                  -> TIMESTAMP (without time zone, same semantics)
--   DECIMAL(p,s)              -> NUMERIC(p,s)
--   utf8mb4 / *_ci collation  -> UTF8 encoding; case-insensitive uniqueness kept
--                                where it matters (customer email, category name)
--                                via unique indexes on lower(col)
--   USE db                    -> \connect db
-- =============================================================================

\set ON_ERROR_STOP on

-- WITH (FORCE) terminates any sessions still connected (PG13+).
DROP DATABASE IF EXISTS ecommerce_db WITH (FORCE);
CREATE DATABASE ecommerce_db
    WITH ENCODING   = 'UTF8'
         TEMPLATE   = template0;

\connect ecommerce_db

-- DDL is transactional in PostgreSQL: the whole build either lands or not.
BEGIN;

-- -----------------------------------------------------------------------------
-- categories
-- -----------------------------------------------------------------------------
CREATE TABLE categories (
    id          BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    name        VARCHAR(100)  NOT NULL,
    slug        VARCHAR(100)  NOT NULL,
    description TEXT,
    created_at  TIMESTAMP,
    updated_at  TIMESTAMP,
    CONSTRAINT pk_categories      PRIMARY KEY (id),
    CONSTRAINT uk_categories_slug UNIQUE (slug)
);
-- Case-insensitive uniqueness, matching MySQL utf8mb4_unicode_ci behaviour.
CREATE UNIQUE INDEX uk_categories_name ON categories (lower(name));

-- -----------------------------------------------------------------------------
-- products
-- -----------------------------------------------------------------------------
CREATE TABLE products (
    id             BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    name           VARCHAR(200)  NOT NULL,
    description    TEXT,
    price          NUMERIC(10,2) NOT NULL,
    sku            VARCHAR(100)  NOT NULL,
    stock_quantity INTEGER       NOT NULL DEFAULT 0,
    active         BOOLEAN       NOT NULL DEFAULT TRUE,
    category_id    BIGINT        NOT NULL,
    created_at     TIMESTAMP,
    updated_at     TIMESTAMP,
    CONSTRAINT pk_products          PRIMARY KEY (id),
    CONSTRAINT uk_products_sku      UNIQUE (sku),
    CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories (id)
);

-- -----------------------------------------------------------------------------
-- customers
-- -----------------------------------------------------------------------------
CREATE TABLE customers (
    id         BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    first_name VARCHAR(100)  NOT NULL,
    last_name  VARCHAR(100)  NOT NULL,
    email      VARCHAR(255)  NOT NULL,
    phone      VARCHAR(20),
    address    TEXT,
    created_at TIMESTAMP,
    CONSTRAINT pk_customers PRIMARY KEY (id)
);
-- Case-insensitive uniqueness, matching MySQL utf8mb4_unicode_ci behaviour.
CREATE UNIQUE INDEX uk_customers_email ON customers (lower(email));

-- -----------------------------------------------------------------------------
-- orders
-- -----------------------------------------------------------------------------
CREATE TABLE orders (
    id               BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    order_number     VARCHAR(20)   NOT NULL,
    customer_id      BIGINT        NOT NULL,
    status           VARCHAR(20)   NOT NULL DEFAULT 'PENDING',
    total_amount     NUMERIC(12,2) NOT NULL DEFAULT 0.00,
    shipping_address TEXT          NOT NULL,
    notes            TEXT,
    created_at       TIMESTAMP,
    updated_at       TIMESTAMP,
    CONSTRAINT pk_orders              PRIMARY KEY (id),
    CONSTRAINT uk_orders_order_number UNIQUE (order_number),
    CONSTRAINT fk_orders_customer     FOREIGN KEY (customer_id) REFERENCES customers (id)
);

-- -----------------------------------------------------------------------------
-- order_items
-- -----------------------------------------------------------------------------
CREATE TABLE order_items (
    id         BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    order_id   BIGINT        NOT NULL,
    product_id BIGINT        NOT NULL,
    quantity   INTEGER       NOT NULL,
    unit_price NUMERIC(10,2) NOT NULL,
    subtotal   NUMERIC(12,2) NOT NULL,
    CONSTRAINT pk_order_items         PRIMARY KEY (id),
    CONSTRAINT fk_order_items_order   FOREIGN KEY (order_id)   REFERENCES orders   (id),
    CONSTRAINT fk_order_items_product FOREIGN KEY (product_id) REFERENCES products (id)
);

-- -----------------------------------------------------------------------------
-- payments
-- -----------------------------------------------------------------------------
CREATE TABLE payments (
    id             BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    order_id       BIGINT        NOT NULL,
    payment_method VARCHAR(30)   NOT NULL,
    payment_status VARCHAR(20)   NOT NULL DEFAULT 'PENDING',
    amount         NUMERIC(12,2) NOT NULL,
    created_at     TIMESTAMP,
    CONSTRAINT pk_payments          PRIMARY KEY (id),
    CONSTRAINT uk_payments_order_id UNIQUE (order_id),   -- also serves the FK
    CONSTRAINT fk_payments_order    FOREIGN KEY (order_id) REFERENCES orders (id)
);

-- -----------------------------------------------------------------------------
-- indexes
-- PostgreSQL does NOT auto-index FK columns (MySQL/InnoDB does), so every
-- referencing column is covered explicitly below (payments.order_id is
-- already covered by its unique constraint).
-- -----------------------------------------------------------------------------
CREATE INDEX idx_products_category   ON products    (category_id);
CREATE INDEX idx_products_active     ON products    (active);
CREATE INDEX idx_orders_customer     ON orders      (customer_id);
CREATE INDEX idx_orders_status       ON orders      (status);
CREATE INDEX idx_order_items_order   ON order_items (order_id);
CREATE INDEX idx_order_items_product ON order_items (product_id);

-- ---------------------------------------------------------------------------
-- Seed data (reference data + customers only).
-- Orders, order_items and payments are intentionally left empty — create those
-- through the API so order-number generation, stock reduction and the cascade
-- save all run as designed.
-- ---------------------------------------------------------------------------

-- categories
INSERT INTO categories (name, slug, description, created_at, updated_at) VALUES
('Electronics',    'electronics',    'Gadgets, accessories and devices',   now(), now()),
('Books',          'books',          'Printed and reference books',        now(), now()),
('Clothing',       'clothing',       'Apparel and everyday wear',          now(), now()),
('Home & Kitchen', 'home-kitchen',   'Homeware and kitchen essentials',    now(), now());

-- products (category resolved by slug rather than hard-coded ids)
INSERT INTO products (name, description, price, sku, stock_quantity, active, category_id, created_at, updated_at)
SELECT v.name, v.description, v.price, v.sku, v.stock_quantity, TRUE, c.id, now(), now()
FROM (VALUES
    ( 1, 'Wireless Mouse',              'Ergonomic 2.4GHz wireless mouse',            24.99, 'ELEC-MOU-001', 150, 'electronics'),
    ( 2, 'Mechanical Keyboard',         'Tactile mechanical keyboard, RGB backlit',   79.99, 'ELEC-KEY-002',  80, 'electronics'),
    ( 3, 'USB-C Hub',                   '7-in-1 USB-C multiport adapter',             39.99, 'ELEC-HUB-003',  60, 'electronics'),
    ( 4, 'Noise-Cancelling Headphones', 'Over-ear ANC wireless headphones',          199.99, 'ELEC-HDP-004',  40, 'electronics'),
    ( 5, 'Clean Code',                  'A Handbook of Agile Software Craftsmanship', 32.50, 'BOOK-CLN-001', 200, 'books'),
    ( 6, 'The Pragmatic Programmer',    'Your Journey to Mastery',                    41.00, 'BOOK-PRG-002', 120, 'books'),
    ( 7, 'Cotton T-Shirt',              'Soft 100% cotton crew-neck tee',             15.00, 'CLTH-TSH-001', 300, 'clothing'),
    ( 8, 'Hooded Sweatshirt',           'Fleece-lined pullover hoodie',               45.00, 'CLTH-HOD-002',  90, 'clothing'),
    ( 9, 'Stainless Steel Bottle',      'Insulated 750ml water bottle',               18.99, 'HOME-BTL-001', 250, 'home-kitchen'),
    (10, 'Ceramic Coffee Mug',          '350ml glazed ceramic mug',                   12.50, 'HOME-MUG-002', 180, 'home-kitchen')
) AS v(seq, name, description, price, sku, stock_quantity, category_slug)
JOIN categories c ON c.slug = v.category_slug
ORDER BY v.seq;   -- keeps ids identical to the MySQL seed (1..10)

-- customers
INSERT INTO customers (first_name, last_name, email, phone, address, created_at) VALUES
('John',  'Doe',   'john.doe@example.com',   '+1-202-555-0101', '123 Maple Street, Springfield', now()),
('Jane',  'Smith', 'jane.smith@example.com', '+1-202-555-0142', '88 Oak Avenue, Riverdale',       now()),
('Ravi',  'Kumar', 'ravi.kumar@example.com', '+91-90000-12345', '12 MG Road, Bengaluru',          now());

COMMIT;

-- Refresh planner statistics after the bulk load.
ANALYZE;

-- ---------------------------------------------------------------------------
-- Verification (run after the script to confirm the seed loaded)
-- ---------------------------------------------------------------------------
SELECT * FROM categories  ORDER BY id;
SELECT * FROM products    ORDER BY id;
SELECT * FROM customers   ORDER BY id;
SELECT * FROM orders      ORDER BY id;
SELECT * FROM order_items ORDER BY id;
SELECT * FROM payments    ORDER BY id;
